# Resumen extractivo y abstractivo: operaciones de larga duración (poller)
poller = client.begin_extract_summary([texto_largo])
for r in poller.result():
    if r.kind == "ExtractiveSummarization":
        print(" ".join(s.text for s in r.sentences))
    elif r.is_error:
        print("Error:", r.error.code, r.error.message)

poller = client.begin_abstract_summary([texto_largo])
for r in poller.result():
    if r.kind == "AbstractiveSummarization":
        for s in r.summaries:
            print(s.text)

