todo = " ".join(r["text"] for r in reviews)
poller = client.begin_extract_summary([todo], max_sentence_count=3)
for res in poller.result():
    if res.kind == "ExtractiveSummarization":
        for s in res.sentences:
            print(round(s.rank_score, 2), s.text)

import json
lang = {r["id"]: r for r in json.load(open("report.json"))["reviews"]}
g1 = {r["id"]: r for r in json.load(open("report_gpt_1.json"))}
g2 = {r["id"]: r for r in json.load(open("report_gpt_2.json"))}
for i in lang:
    same = set(map(str.lower, g1[i]["key_phrases"])) & set(map(str.lower, g2[i]["key_phrases"]))
    print(i, "Language:", lang[i].get("sentiment"), "| GPT1:", g1[i]["sentiment"],
          "| GPT2:", g2[i]["sentiment"], "| frases comunes GPT1/GPT2:", len(same))
